        partialWrites &&
        Boolean(baseline) &&
        body.patients.length <= 200 &&
        body.services.length <= 200;
      if (state.lazyReads && !useChanges)
        throw new Error(
          'Слишком много изменений за один раз. Сохраняйте не более 200 карточек или услуг.',
        );
