function createEditor(state, actions) {
  let baseline = '',
    baselinePhotos = [],
    closing = false,
    touched = false,
    suspendedAppointment = null;
  function editorSnapshot() {
    const fields = [...actions.$('#form-content').querySelectorAll('input, select, textarea')]
      .filter((field) => !['button', 'submit'].includes(field.type))
      .map((field) => [
        field.dataset.creationField || field.name || field.id,
        field.value,
        field.checked,
        [...(field.files || [])].map((file) => [file.name, file.size, file.lastModified]),
      ]);
    return JSON.stringify([
      fields,
      state.editorMode?.serviceItems,
      (state.uploadItems || []).map((item) => [item.id, item.caption, item.name]),
    ]);
  }
  function editorHasChanges() {
    return Boolean(
      state.editorMode &&
      (baseline !== editorSnapshot() ||
        actions.photosPending() ||
        baselinePhotos.some((photo, i) => photo !== state.uploadItems[i])),
    );
  }
  async function requestEditorClose() {
    if (state.busy || closing) return;
    if (suspendedAppointment && actions.cabinetSaveStatus()) {
      actions.renderSaveRecovery();
      return;
    }
    const mode = state.editorMode;
    closing = true;
    try {
      if (
        editorHasChanges() &&
        !(await actions.confirmAction(
          'Закрыть форму?',
          'Несохранённые изменения будут потеряны.',
          'Закрыть без сохранения',
          'Продолжить',
          { preferCancel: true },
        ))
      )
        return;
      if (!state.busy && state.editorMode === mode && !restoreAppointmentEditor()) closeEditor();
    } finally {
      closing = false;
    }
  }
  function bindEditorCloseEvents() {
    const content = actions.$('#form-content');
    for (const type of ['input', 'change', 'click'])
      content.addEventListener(
        type,
        () => {
          touched = true;
        },
        true,
      );
    new window.MutationObserver(() => {
      if (state.editorMode && !touched) baseline = editorSnapshot();
    }).observe(content, { childList: true, subtree: true });
    actions.$('#editor').addEventListener('cancel', (event) => {
      event.preventDefault();
      void requestEditorClose();
    });
    window.addEventListener('beforeunload', (event) => {
      if (!editorHasChanges() && !suspendedAppointment?.dirty) return;
      event.preventDefault();
      event.returnValue = '';
    });
  }
  function suspendAppointmentEditor() {
    if (state.busy || state.editorMode?.kind !== 'appointment' || suspendedAppointment)
      return false;
    const title = actions.$('#dialog-title'),
      save = actions.$('#save-editor'),
      tabs = actions.$('#calendar-creation-tabs');
    suspendedAppointment = {
      account: state.account,
      mode: state.editorMode,
      nodes: [...actions.$('#form-content').childNodes],
      title: title.textContent,
      titleHidden: title.hidden,
      closeHidden: actions.$('#close-editor').hidden,
      saveHidden: save.hidden,
      saveText: save.textContent,
      error: actions.$('#form-error').textContent,
      labelledBy: actions.$('#editor').getAttribute('aria-labelledby'),
      scrollTop: actions.$('#editor-form').scrollTop,
      tabs,
      baseline,
      baselinePhotos,
      touched,
      dirty: editorHasChanges(),
    };
    tabs?.remove();
    return true;
  }
  function restoreAppointmentEditor(createdId = '') {
    const saved = suspendedAppointment;
    if (!saved || state.editorMode?.kind !== 'service') return false;
    suspendedAppointment = null;
    if (saved.account !== state.account || !actions.$('#editor').open) return false;
    state.editorMode = saved.mode;
    const content = actions.$('#form-content'),
      title = actions.$('#dialog-title'),
      save = actions.$('#save-editor');
    content.replaceChildren(...saved.nodes);
    content.inert = false;
    title.textContent = saved.title;
    title.hidden = saved.titleHidden;
    if (saved.tabs) title.after(saved.tabs);
    actions.$('#close-editor').hidden = saved.closeHidden;
    save.hidden = saved.saveHidden;
    save.textContent = saved.saveText;
    actions.$('#form-error').textContent = saved.error;
    actions.$('#editor').dataset.editorKind = saved.mode.kind;
    actions.$('#editor').setAttribute('aria-labelledby', saved.labelledBy || 'dialog-title');
    actions.$('#editor-form').scrollTop = saved.scrollTop;
    baseline = saved.baseline;
    baselinePhotos = saved.baselinePhotos;
    touched = saved.touched;
    actions.mountAppointmentTimePicker?.();
    actions.refreshAppointmentServices(createdId);
    actions.updatePhotoSaveButton();
    return true;
  }
  function openDialog() {
    actions.cancelPhotoProcessing();
    actions.$('#form-error').textContent = '';
    actions.$('#form-content').inert = false;
    actions.$('#save-editor').hidden = [
      'appointmentOutcome',
      'appointmentActions',
      'patientMarkView',
    ].includes(state.editorMode?.kind);
    actions.mountServiceGroupControl();
    if (suspendedAppointment && state.editorMode?.kind === 'service') {
      actions.$('#dialog-title').hidden = false;
      actions.$('#close-editor').hidden = false;
      actions.$('#save-editor').textContent = 'Сохранить';
    } else {
      suspendedAppointment = null;
      actions.mountCalendarCreationTabs?.();
    }
    actions.mountAppointmentTimePicker?.();
    const d = actions.$('#editor');
    d.classList.toggle('editor-designed', Boolean(state.multiUser));
    d.dataset.editorKind = state.editorMode?.kind || '';
    d.setAttribute('aria-labelledby', 'dialog-title');
    if (!d.open) d.showModal();
    actions.renderSaveRecovery();
    actions.updatePhotoSaveButton();
    baseline = editorSnapshot();
    baselinePhotos = [...state.uploadItems];
    touched = false;
  }
  async function submit(e) {
    e.preventDefault();
    if (
      state.busy ||
      !state.editorMode ||
      ['appointmentOutcome', 'appointmentActions', 'patientMarkView'].includes(
        state.editorMode.kind,
      )
    )
      return;
    if (actions.photosPending()) {
      actions.$('#form-error').textContent = 'Дождитесь обработки фотографий перед сохранением.';
      return;
    }
    if (actions.cabinetSaveStatus()) {
      actions.renderSaveRecovery();
      return;
    }
    state.busy = true;
    actions.$('#save-editor').disabled = true;
    try {
      const f = new FormData(e.target),
        v = Object.fromEntries(f.entries());
      actions.$('#form-error').textContent = '';
      const commands = {
        workSchedule: actions.saveWorkScheduleForm,
        service: actions.saveServiceForm,
        appointment: actions.saveAppointmentForm,
        personalEvent: actions.savePersonalEventForm,
        patient: actions.savePatientForm,
        patientMark: actions.savePatientMarkForm,
        visit: actions.saveVisitForm,
      };
      const command = commands[state.editorMode.kind];
      if (!command) throw new Error('Неизвестный режим формы.');
      const task = command(v);
      // Synchronous validation must release the form before the next input event.
      if (task) await task;
    } catch (error) {
      actions.rollback();
      actions.$('#form-error').textContent = error.message;
      actions.renderSaveRecovery();
    } finally {
      state.busy = false;
      actions.updatePhotoSaveButton();
    }
  }
  function discardAssistantDraft() {
    const draft = state.assistantEditor;
    if (!draft) return;
    state.assistantEditor = null;
    if (state.editorMode === draft || suspendedAppointment?.mode === draft) closeEditor();
  }
  function closeEditor() {
    state.assistantEditor = null;
    suspendedAppointment = null;
    actions.cancelPhotoProcessing();
    const d = actions.$('#editor');
    if (d.open) d.close();
    actions.$('#save-editor').hidden = false;
    actions.$('#form-content').inert = false;
    state.editorMode = null;
    state.appointmentFromServices = false;
    state.uploadItems = [];
    actions.resetCalendarCreationTabs?.();
    baseline = '';
    baselinePhotos = [];
  }
  return {
    openDialog,
    submit,
    closeEditor,
    discardAssistantDraft,
    requestEditorClose,
    bindEditorCloseEvents,
    suspendAppointmentEditor,
    restoreAppointmentEditor,
  };
}

function createFormat(state, actions) {
  const $ = (s, root = document) => root.querySelector(s);
  const esc = (v = '') =>
    String(v).replace(
      /[&<>"']/g,
      (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
    );
  const formatDate = (v) =>
    v
      ? new Intl.DateTimeFormat('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' }).format(
          new Date(v + 'T00:00:00'),
        )
      : '—';
  function formatPhone(value) {
    const original = String(value || '').trim(),
      raw = actions.normalizePatientPhoneText(original);
    if (raw === null) return original;
    const digits = raw.replace(/\D/g, ''),
      national =
        digits.length === 11 &&
        (digits.startsWith('7') || (digits.startsWith('8') && !raw.startsWith('+')))
          ? digits.slice(1)
          : digits.length === 10 && !raw.startsWith('+')
            ? digits
            : '';
    return national
      ? `+7 (${national.slice(0, 3)}) ${national.slice(3, 6)}-${national.slice(6, 8)}-${national.slice(8)}`
      : raw;
  }
  const isoDate = (d) => {
    const x = new Date(d);
    return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, '0')}-${String(x.getDate()).padStart(2, '0')}`;
  };
  const parseDate = (v) => new Date(`${v}T00:00:00`);
  const monthTitle = (d) =>
    new Intl.DateTimeFormat('ru-RU', { month: 'long', year: 'numeric' })
      .format(d)
      .replace(/^./, (c) => c.toUpperCase());
  const weekStart = (d) => {
    const x = new Date(d);
    const day = (x.getDay() + 6) % 7;
    x.setDate(x.getDate() - day);
    x.setHours(0, 0, 0, 0);
    return x;
  };
  const timeLabel = (minutes) =>
    `${String(Math.floor(minutes / 60)).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')}`;
  const initials = (name) =>
    name
      .split(/\s+/)
      .slice(0, 2)
      .map((x) => x[0])
      .join('')
      .toUpperCase();
  function plural(n, a, b, c) {
    const x = n % 100;
    return x >= 11 && x <= 14 ? c : n % 10 === 1 ? a : n % 10 >= 2 && n % 10 <= 4 ? b : c;
  }
  function toast(msg) {
    const t = actions.$('#toast');
    t.textContent = msg;
    t.classList.add('visible');
    setTimeout(() => t.classList.remove('visible'), 4000);
  }
  return {
    $,
    esc,
    formatDate,
    formatPhone,
    isoDate,
    parseDate,
    monthTitle,
    weekStart,
    timeLabel,
    initials,
    plural,
    toast,
  };
}

function createAccess(state, actions) {
  const accountRole = () => state.account?.role || 'owner';
  const accountId = () => state.account?.id || 'legacy-owner';
  const canManageTeam = () => ['owner', 'salon_admin'].includes(actions.accountRole());
  const canManageMembers = () => actions.accountRole() === 'owner';
  const canEditServices = () => ['owner', 'salon_admin'].includes(actions.accountRole());
  const canEditPatient = () => ['owner', 'salon_admin'].includes(actions.accountRole());
  const canDelete = () => actions.accountRole() === 'owner';
  const canEditRecord = (record) =>
    actions.accountRole() !== 'cosmetologist' || record?.staffId === actions.accountId();
  function lockSavedVisit(v) {
    if (!v?.id || actions.accountRole() === 'owner') return;
    state.editorMode.appendOnly = true;
    state.editorMode.savedPhotoCount = (v.photos || []).length;
    actions.$('#dialog-title').textContent = 'Дополнить посещение';
    const content = actions.$('#form-content');
    for (const field of content.querySelectorAll(
      'input:not([type="file"]):not([type="hidden"]),select,textarea:not([name="notes"])',
    ))
      field.disabled = true;
    for (const button of content.querySelectorAll(
      '[data-remove-visit-procedure],[data-remove-visit-legacy]',
    ))
      button.hidden = true;
    const hint = document.createElement('p');
    hint.className = 'form-hint';
    hint.textContent =
      'Сведения проведённого посещения сохранены. Можно добавить заметки и фотографии; исправления доступны владельцу.';
    content.prepend(hint);
    const notes = content.querySelector('[name="notes"]');
    notes.value = '';
    notes.placeholder = 'Дополнение к сохранённому посещению';
    if (v.notes) {
      const prior = document.createElement('p');
      prior.className = 'note';
      prior.textContent = v.notes;
      notes.before(prior);
    }
  }
  return {
    accountRole,
    accountId,
    canManageTeam,
    canManageMembers,
    canEditServices,
    canEditPatient,
    canDelete,
    canEditRecord,
    lockSavedVisit,
  };
}

function createStaffField(state, actions) {
  function staffField(current = '', locked = false) {
    if (locked) {
      const member = state.teamAccess?.members.find((member) => member.accountId === current);
      const name =
        member?.displayName ||
        (current === actions.accountId() ? state.account?.displayName : '') ||
        'Специалист исходной записи';
      return (
        '<label class="field full">Специалист<input readonly value="' +
        actions.esc(name) +
        '"></label><input type="hidden" name="staffId" value="' +
        actions.esc(current || actions.accountId()) +
        '">'
      );
    }
    const active = (state.teamAccess?.members || []).filter(
      (member) => member.status === 'active' && ['owner', 'cosmetologist'].includes(member.role),
    );
    if (!actions.canManageTeam() || !active.length)
      return `<input type="hidden" name="staffId" value="${actions.esc(current || actions.accountId())}">`;
    return [
      `<label class="field full">Специалист<select name="staffId" required>${active.map((member) => `<option value="${actions.esc(member.accountId)}" ${member.accountId === (current || actions.accountId()) ? 'selected' : ''}>${actions.esc(member.displayName)} · ${actions.esc(state.roleNames[member.role] || member.role)}</option>`).join('')}</select>`,
      `</label>`,
    ].join('');
  }
  return { staffField };
}

function createDeferredSettings(state, actions, install, load = (url) => import(url)) {
  let pending = null,
    scheduled = false,
    attempt = 0,
    terminalError = null,
    deferred = null,
    departed = false;
  const reloadError = () =>
    Object.assign(
      new Error('Версия приложения обновилась. Сохраните изменения и обновите страницу.'),
      { reloadRequired: true },
    );
  const loadFailure = () => new Error('Не удалось загрузить настройки. Проверьте соединение.');
  const release = () => document.querySelector('meta[name="cartoteca-build"]')?.content;
  const sameLoadContext = (entry) =>
    state.account === entry.account &&
    entry.identity ===
      JSON.stringify([state.account?.id, state.account?.organizationId, state.account?.role]) &&
    state.settingsBundleId === entry.bundle &&
    release() === entry.release;
  const passiveCurrent = (entry) =>
    sameLoadContext(entry) && !entry.inactive && !document.hidden && !departed;
  const canDiagnose = (entry) =>
    !entry.passive || (sameLoadContext(entry) && (entry.manual || passiveCurrent(entry)));
  function watchPassiveLoad(entry) {
    if (!entry.passive) return () => {};
    const hidden = () => {
      if (!document.hidden) return;
      entry.inactive = true;
      entry.cancelDiagnostic?.();
    };
    const leave = () => {
      entry.inactive = true;
      entry.cancelDiagnostic?.();
    };
    document.addEventListener?.('visibilitychange', hidden);
    window.addEventListener?.('pagehide', leave);
    return () => {
      document.removeEventListener?.('visibilitychange', hidden);
      window.removeEventListener?.('pagehide', leave);
    };
  }
  async function describeLoadFailure(url, entry) {
    if (!canDiagnose(entry)) return loadFailure();
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 3000);
    const cancel = () => {
      if (!canDiagnose(entry)) controller.abort();
    };
    entry.cancelDiagnostic = cancel;
    try {
      if (!canDiagnose(entry)) return loadFailure();
      // Import errors hide HTTP status. Inspect only a current load failure, never prefetch APIs.
      const response = await fetch(url, {
        method: 'HEAD',
        cache: 'no-store',
        signal: controller.signal,
      });
      if (!canDiagnose(entry)) return loadFailure();
      if (response.status === 409) return reloadError();
      if (response.status === 401)
        return Object.assign(new Error('Сессия завершилась. Обновите страницу и войдите снова.'), {
          reloadRequired: true,
        });
    } catch {
    } finally {
      clearTimeout(timer);
      if (entry.cancelDiagnostic === cancel) entry.cancelDiagnostic = null;
    }
    return loadFailure();
  }
  async function loadSettings(passive) {
    if (terminalError) throw terminalError;
    if (state.settingsReady) return;
    if (pending) {
      // Explicit navigation may join the same transport and still needs an actionable error.
      if (!passive && sameLoadContext(pending)) {
        pending.manual = true;
        pending.promote?.();
      }
      return pending.promise;
    }
    const entry = {
      account: state.account,
      identity: JSON.stringify([
        state.account?.id,
        state.account?.organizationId,
        state.account?.role,
      ]),
      bundle: state.settingsBundleId,
      release: release(),
      passive,
      manual: !passive,
      inactive: document.hidden || departed,
      cancelDiagnostic: null,
      promise: null,
    };
    const unwatch = watchPassiveLoad(entry);
    const task = (async () => {
      if (!entry.release || !state.settingsBundleId)
        throw new Error('Обновите страницу, чтобы загрузить настройки этой версии.');
      const suffix = attempt++ ? '&attempt=' + attempt : '';
      const resource = document.querySelector(
        'meta[name="cartoteca-resource-app-settings"]',
      )?.content;
      const version = resource && resource !== entry.release ? resource : entry.release;
      const url =
        '/app-settings.js?v=' +
        encodeURIComponent(version) +
        (version !== entry.release ? '&build=' + encodeURIComponent(entry.release) : '') +
        suffix;
      const importKey = JSON.stringify([
        'settings',
        state.account?.id,
        state.account?.organizationId,
        state.account?.role,
        url,
      ]);
      const importModule = () => {
        if (
          !sameLoadContext(entry) ||
          (entry.passive && !entry.manual && (document.hidden || departed))
        )
          throw loadFailure();
        return load(url);
      };
      entry.promote = () =>
        actions
          .scheduleRead?.(importModule, { priority: 'user', key: importKey, timeoutMs: 15000 })
          .catch(() => {});
      let module, timer;
      try {
        module = await Promise.race([
          actions.scheduleRead
            ? actions.scheduleRead(importModule, {
                priority: passive ? 'background' : 'user',
                key: importKey,
                timeoutMs: 15000,
              })
            : load(url),
          new Promise((resolve, reject) => {
            timer = setTimeout(() => reject(new Error('Settings load timeout')), 15000);
          }),
        ]);
      } catch {
        throw await describeLoadFailure(url, entry);
      } finally {
        clearTimeout(timer);
      }
      if (module.bundleId !== state.settingsBundleId) throw reloadError();
      if (!sameLoadContext(entry))
        throw new Error('Учётная запись изменилась. Повторите открытие настроек.');
      try {
        install(module);
      } catch {
        // A factory/bind failure may already have attached listeners. Never repeat it.
        terminalError = Object.assign(
          new Error('Не удалось подключить настройки. Сохраните изменения и обновите страницу.'),
          { reloadRequired: true },
        );
        throw terminalError;
      }
      state.settingsReady = true;
      cancelDeferredLoad();
    })();
    entry.promise = task;
    pending = entry;
    let resumePassive = false;
    try {
      await task;
    } catch (error) {
      if (passive) {
        if (passiveCurrent(entry))
          actions.toast(
            error.reloadRequired
              ? error.message
              : 'Не удалось загрузить настройки. Откройте их, чтобы повторить загрузку.',
          );
        else if (!entry.manual && entry.inactive && sameLoadContext(entry) && !terminalError)
          resumePassive = true;
      }
      throw error;
    } finally {
      unwatch();
      if (pending === entry) pending = null;
      if (resumePassive) queueSettingsLoad();
    }
  }
  function ensureSettings() {
    return loadSettings(false);
  }
  function clearDeferredHandles(job) {
    clearTimeout(job.fallback);
    clearTimeout(job.task);
    if (job.frame !== null) window.cancelAnimationFrame?.(job.frame);
    if (job.secondFrame !== null) window.cancelAnimationFrame?.(job.secondFrame);
    if (job.idle !== null) window.cancelIdleCallback?.(job.idle);
    job.fallback = job.task = job.frame = job.secondFrame = job.idle = null;
  }
  function cancelDeferredLoad() {
    const job = deferred;
    deferred = null;
    if (!job) return;
    job.phase++;
    clearDeferredHandles(job);
    document.removeEventListener?.('visibilitychange', job.visible);
  }
  function queueSettingsLoad() {
    if (deferred || departed || state.settingsReady || terminalError) return;
    const job = {
      phase: 0,
      fallback: null,
      task: null,
      frame: null,
      secondFrame: null,
      idle: null,
      visible: null,
    };
    deferred = job;
    const current = () => deferred === job && !departed && !state.settingsReady;
    const afterPaint = () => {
      job.phase++;
      clearDeferredHandles(job);
      if (!current()) {
        cancelDeferredLoad();
        return;
      }
      if (document.hidden) return;
      const phase = job.phase;
      let started = false;
      const phaseCurrent = () => current() && phase === job.phase;
      const run = () => {
        if (!phaseCurrent()) return;
        if (document.hidden) {
          job.phase++;
          clearDeferredHandles(job);
          return;
        }
        cancelDeferredLoad();
        void loadSettings(true).catch(() => {});
      };
      const ready = () => {
        if (started || !phaseCurrent()) return;
        started = true;
        clearDeferredHandles(job);
        if (document.hidden) return;
        if (window.requestIdleCallback)
          job.idle = window.requestIdleCallback(run, { timeout: 1000 });
        else job.task = setTimeout(run, 0);
      };
      // Keep automatic loading after visible paints; fallback still covers throttled frames.
      job.fallback = setTimeout(ready, 1500);
      if (window.requestAnimationFrame)
        job.frame = window.requestAnimationFrame(() => {
          job.frame = null;
          if (!phaseCurrent()) return;
          job.secondFrame = window.requestAnimationFrame(() => {
            job.secondFrame = null;
            ready();
          });
        });
    };
    job.visible = () => {
      if (deferred !== job) return;
      if (document.hidden) {
        job.phase++;
        clearDeferredHandles(job);
      } else afterPaint();
    };
    document.addEventListener?.('visibilitychange', job.visible);
    afterPaint();
  }
  function scheduleSettingsLoad() {
    if (scheduled || state.settingsReady) return;
    scheduled = true;
    queueSettingsLoad();
  }
  window.addEventListener?.('pagehide', () => {
    departed = true;
    cancelDeferredLoad();
  });
  window.addEventListener?.('pageshow', () => {
    departed = false;
    if (scheduled && !pending) queueSettingsLoad();
  });
  return { ensureSettings, scheduleSettingsLoad };
}

function createNotificationHistory(state, actions) {
  const pending = new WeakSet();
  const labels = { telegram: 'Telegram', max: 'MAX', push: 'Push', manual: 'Сотрудник' };
  const kinds = {
    reminder: 'Напоминание',
    'booking-confirmed': 'Запись создана',
    created: 'Запись создана',
    moved: 'Перенос',
    cancelled: 'Отмена',
    confirmation: 'Подтверждение записи',
  };
  const statuses = {
    queued: 'В очереди',
    sending: 'Отправляется',
    accepted: 'Принято сервисом',
    failed: 'Ошибка отправки',
    unknown: 'Результат неизвестен',
    cancelled: 'Отменено',
    'client-confirmed': 'Клиент подтвердил',
    'staff-confirmed': 'Подтверждено сотрудником',
  };
  function notificationHistoryHtml(patientId, appointmentId) {
    return (
      '<details class="appointment-notification-history" data-notification-history data-patient-id="' +
      actions.esc(patientId) +
      '" data-notification-appointment-id="' +
      actions.esc(appointmentId) +
      '"><summary>История уведомлений</summary><div data-notification-history-content role="status">Откройте историю для загрузки.</div></details>'
    );
  }
  async function loadHistory(section) {
    if (!section?.open || pending.has(section)) return;
    const account = state.account,
      expectedScope = JSON.stringify([state.account?.id, state.account?.organizationId]),
      patientId = section.dataset.patientId,
      appointmentId = section.dataset.notificationAppointmentId;
    const current = () =>
      section.isConnected &&
      state.account === account &&
      JSON.stringify([state.account?.id, state.account?.organizationId]) === expectedScope &&
      section.open;
    pending.add(section);
    const content = section.querySelector('[data-notification-history-content]');
    content.textContent = 'Загружаем историю…';
    try {
      const result = await actions.request(
        '/api/notifications/history?' + new URLSearchParams({ patientId, appointmentId }),
      );
      if (!current()) return;
      const rows = result.items
        .map((item) => {
          const at =
            item.confirmedAt || item.acceptedAt || item.updatedAt || item.createdAt || item.eventAt;
          const time = Number.isFinite(at)
            ? new Date(at).toLocaleString('ru-RU', { timeZone: state.timeZone })
            : 'Время не сохранено';
          return (
            '<li><strong>' +
            actions.esc(kinds[item.kind] || 'Уведомление') +
            '</strong><span>' +
            actions.esc(labels[item.channel] || 'Картотека') +
            ' · ' +
            actions.esc(statuses[item.status] || 'Состояние уточняется') +
            '</span><small>' +
            actions.esc(time) +
            '</small></li>'
          );
        })
        .join('');
      content.innerHTML =
        (rows
          ? '<ul class="notification-history-list">' + rows + '</ul>'
          : '<p>История отправок пока пуста.</p>') +
        (result.limited ? '<p class="form-hint">Показана доступная часть истории.</p>' : '') +
        '<p class="form-hint">Принятие сообщения сервисом не подтверждает его прочтение.</p><button type="button" class="text-btn" data-notification-history-retry>Обновить</button>';
    } catch (error) {
      if (current())
        content.innerHTML =
          '<p class="error">' +
          actions.esc(error.message) +
          '</p><button type="button" class="secondary" data-notification-history-retry>Повторить</button>';
    } finally {
      pending.delete(section);
    }
  }
  function bindNotificationHistoryEvents() {
    document.addEventListener(
      'toggle',
      (event) => {
        if (event.target.matches?.('[data-notification-history]') && event.target.open)
          void loadHistory(event.target);
      },
      true,
    );
    document.addEventListener('click', (event) => {
      if (event.target.closest('[data-notification-history-retry]'))
        void loadHistory(event.target.closest('[data-notification-history]'));
    });
  }
  return { notificationHistoryHtml, bindNotificationHistoryEvents };
}

function createAssistantHost(state, actions, install, load = (url) => import(url)) {
  let activeKey = '',
    pending = null,
    scheduled = false,
    deferred = null,
    installed = false,
    terminal = false,
    visibleRetry = null;
  const key = () =>
    JSON.stringify([state.account?.id, state.account?.organizationId, state.account?.role]);
  const permitted = (scope) =>
    Boolean(
      state.multiUser &&
      state.account?.organizationId &&
      scope?.enabled === true &&
      scope.organizationId === state.account.organizationId,
    );
  function clearDeferredHandles(job) {
    clearTimeout(job.fallback);
    clearTimeout(job.task);
    if (job.frame !== null) window.cancelAnimationFrame?.(job.frame);
    if (job.secondFrame !== null) window.cancelAnimationFrame?.(job.secondFrame);
    if (job.idle !== null) window.cancelIdleCallback?.(job.idle);
    job.fallback = job.task = job.frame = job.secondFrame = job.idle = null;
  }
  function cancelDeferredLoad() {
    const job = deferred;
    deferred = null;
    if (!job) return;
    job.phase++;
    clearDeferredHandles(job);
    document.removeEventListener?.('visibilitychange', job.visible);
  }
  function resetAssistant() {
    if (visibleRetry) document.removeEventListener?.('visibilitychange', visibleRetry);
    visibleRetry = null;
    state.assistantGeneration++;
    cancelDeferredLoad();
    if (installed) actions.destroyVoiceAssistant();
    state.assistantScope = null;
    state.assistantReady = false;
    activeKey = '';
    scheduled = false;
    pending = null;
  }
  function applyAssistantScope(scope = null) {
    const changed =
      activeKey &&
      (activeKey !== key() || state.assistantScope?.policyVersion !== scope?.policyVersion);
    if (changed || !permitted(scope)) resetAssistant();
    if (!permitted(scope)) return;
    activeKey = key();
    state.assistantScope = scope;
    if (installed) state.assistantReady = true;
    if (state.sessionReady) scheduleAssistantLoad();
  }
  function mountAssistant() {
    if (activeKey && activeKey !== key()) resetAssistant();
    if (installed && state.assistantReady && permitted(state.assistantScope))
      actions.mountVoiceAssistant();
  }
  async function loadAssistant() {
    if (terminal || !permitted(state.assistantScope) || !state.sessionReady) return;
    if (installed) {
      state.assistantReady = true;
      mountAssistant();
      return;
    }
    if (pending) return pending;
    const generation = state.assistantGeneration,
      scopeKey = key();
    const version = document.querySelector('meta[name="cartoteca-build"]')?.content;
    const task = (async () => {
      if (!version || !state.assistantBundleId)
        throw Error('Обновите страницу для запуска помощника.');
      let timer;
      const resource = document.querySelector(
        'meta[name="cartoteca-resource-app-assistant"]',
      )?.content;
      const resourceVersion = resource && resource !== version ? resource : version;
      const url =
        '/app-assistant.js?v=' +
        encodeURIComponent(resourceVersion) +
        (resourceVersion !== version ? '&build=' + encodeURIComponent(version) : '');
      const module = await Promise.race([
        actions.scheduleRead
          ? actions.scheduleRead(
              () => {
                if (
                  generation !== state.assistantGeneration ||
                  scopeKey !== key() ||
                  !permitted(state.assistantScope) ||
                  document.hidden
                )
                  throw Error('Загрузка помощника отложена.');
                return load(url);
              },
              { priority: 'background', timeoutMs: 15000 },
            )
          : load(url),
        new Promise((resolve, reject) => {
          timer = setTimeout(
            () => reject(Error('Помощник не загрузился. Обновите страницу.')),
            15000,
          );
        }),
      ]).finally(() => clearTimeout(timer));
      if (
        generation !== state.assistantGeneration ||
        scopeKey !== key() ||
        !permitted(state.assistantScope)
      )
        return;
      if (module.bundleId !== state.assistantBundleId)
        throw Error('Версия помощника обновилась. Сохраните изменения и обновите страницу.');
      try {
        install(module);
      } catch {
        terminal = true;
        throw Error('Не удалось подключить помощника. Обновите страницу.');
      }
      installed = true;
      state.assistantReady = true;
      mountAssistant();
    })();
    pending = task;
    try {
      await task;
    } finally {
      if (pending === task) pending = null;
    }
  }
  function scheduleAssistantLoad() {
    if (scheduled || !permitted(state.assistantScope) || !state.sessionReady) return;
    scheduled = true;
    const generation = state.assistantGeneration;
    const job = {
      phase: 0,
      fallback: null,
      task: null,
      frame: null,
      secondFrame: null,
      idle: null,
      visible: null,
    };
    deferred = job;
    const current = () => deferred === job && generation === state.assistantGeneration;
    const afterPaint = () => {
      job.phase++;
      clearDeferredHandles(job);
      if (!current() || document.hidden) return;
      const phase = job.phase;
      let started = false;
      const phaseCurrent = () => current() && phase === job.phase;
      const run = () => {
        if (!phaseCurrent()) return;
        if (document.hidden) {
          job.phase++;
          clearDeferredHandles(job);
          return;
        }
        cancelDeferredLoad();
        void loadAssistant().catch((error) => {
          if (generation === state.assistantGeneration) {
            scheduled = false;
            if (!document.hidden) actions.toast(error.message);
            else if (!visibleRetry) {
              visibleRetry = () => {
                if (document.hidden) return;
                document.removeEventListener?.('visibilitychange', visibleRetry);
                visibleRetry = null;
                scheduleAssistantLoad();
              };
              document.addEventListener?.('visibilitychange', visibleRetry);
            }
          }
        });
      };
      const ready = () => {
        if (started || !phaseCurrent()) return;
        started = true;
        clearDeferredHandles(job);
        if (document.hidden) return;
        if (window.requestIdleCallback)
          job.idle = window.requestIdleCallback(run, { timeout: 1000 });
        else job.task = setTimeout(run, 0);
      };
      job.fallback = setTimeout(ready, 1500);
      if (window.requestAnimationFrame)
        job.frame = window.requestAnimationFrame(() => {
          job.frame = null;
          if (!phaseCurrent()) return;
          job.secondFrame = window.requestAnimationFrame(() => {
            job.secondFrame = null;
            ready();
          });
        });
    };
    job.visible = () => {
      if (!current()) return;
      if (document.hidden) {
        job.phase++;
        clearDeferredHandles(job);
      } else afterPaint();
    };
    document.addEventListener?.('visibilitychange', job.visible);
    afterPaint();
  }
  function bindAssistantLifecycle() {
    window.addEventListener('pagehide', resetAssistant);
  }
  return {
    resetAssistant,
    applyAssistantScope,
    mountAssistant,
    scheduleAssistantLoad,
    bindAssistantLifecycle,
  };
}

function bindEvents(state, actions) {
  actions.bindPatientViewEvents();
  const logoutScopeMatches = (intent) =>
    intent.accountId === (state.account?.id || '') &&
    intent.organizationId === (state.account?.organizationId || '');
  actions.bindDialogInteractionEvents();
  actions.bindTimePickerEvents();
  actions.bindManagementEvents();
  actions.bindBookingHealthEvents();
  actions.bindClientContactEvents();
  actions.bindPatientPhoneEvents();
  actions.bindWorkScheduleEvents();
  actions.bindWorkScheduleEditorEvents();
  actions.bindSaveRecoveryEvents();
  actions.bindBackgroundEvents();
  actions.bindAssistantLifecycle();
  actions.bindVideoConsentEvents();
  actions.bindPatientMarkEvents();
  actions.bindServiceGroupEvents();
  actions.bindTelegramSharingEvents();
  actions.bindManualConfirmationEvents();
  actions.bindTelegramEvents();
  actions.bindMaxClientEvents();
  actions.bindMaxInvitationEvents();
  actions.bindSettingsHelpEvents();
  actions.bindAppointmentPatientPickerEvents();
  actions.bindAppointmentWorkflowEvents();
  actions.bindCalendarCreationTabEvents();
  actions.bindPersonalEventEvents();
  actions.bindAppointmentActionEvents();
  actions.bindNotificationHistoryEvents();
  actions.bindAppointmentOutcomeEvents();
  actions.bindVisitProcedureEvents();
  actions.bindAppointmentProcedureEvents();
  actions.bindRoomEvents();
  actions.bindServiceEvents();
  document.addEventListener('click', async (e) => {
    if (state.busy) return;
    let logoutIntent = null;
    try {
      if (actions.handleCalendarLoadNavigation(e.target)) return;
      if (e.target.closest('#print-patient')) {
        e.target.closest('.patient-more')?.removeAttribute('open');
        await actions.printPatient();
        return;
      }
      if (e.target.closest('#logout-account')) {
        logoutIntent = {
          accountId: state.account?.id || '',
          organizationId: state.account?.organizationId || '',
        };
        if (
          !(await actions.confirmSettingsLeave()) ||
          state.busy ||
          !logoutScopeMatches(logoutIntent)
        )
          return;
        actions.resetAssistant();
        await actions.disconnectPushOnLogout?.();
        if (!logoutScopeMatches(logoutIntent)) return;
        await actions.request('/api/auth/logout', { method: 'POST', body: '{}' });
        if (!logoutScopeMatches(logoutIntent)) return;
        if (logoutIntent.accountId) {
          try {
            localStorage.setItem(
              'cartoteca-logout-v2',
              JSON.stringify({ ...logoutIntent, at: Date.now() }),
            );
          } catch {
            // The server revoked this session; unavailable storage must not block leaving it.
          }
        }
        location.replace('/');
        return;
      }
      if (e.target.closest('#migrate-legacy')) {
        state.busy = true;
        await actions.migrateLegacy();
        actions.setView('settings');
        return;
      }
      if (e.target.closest('[data-toggle-month]')) {
        state.monthPickerOpen = !state.monthPickerOpen;
        actions.setView('calendar');
        return;
      }
      const overviewDate = e.target.closest('[data-overview-date]');
      if (overviewDate) {
        state.calendarAnchorDate = actions.parseDate(overviewDate.dataset.overviewDate);
        state.calendarMode = 'day';
        state.monthPickerOpen = false;
        actions.setView('calendar');
        return;
      }
      const calendarDate = e.target.closest('[data-calendar-date]');
      if (calendarDate) {
        state.calendarAnchorDate = actions.parseDate(calendarDate.dataset.calendarDate);
        state.monthPickerOpen = false;
        actions.setView('calendar');
        return;
      }
      if (e.target.closest('[data-toggle-early-hours]')) {
        state.showEarlyHours = !state.showEarlyHours;
        actions.setView('calendar');
        return;
      }
      if (e.target.closest('[data-calendar-today]')) {
        state.calendarAnchorDate = actions.cabinetTodayDate();
        actions.setCalendarMode('day');
        state.monthPickerOpen = false;
        actions.setView('calendar');
        return;
      }
      if (e.target.closest('[data-month-prev]')) {
        state.calendarAnchorDate = new Date(
          state.calendarAnchorDate.getFullYear(),
          state.calendarAnchorDate.getMonth() - 1,
          1,
        );
        actions.setView('calendar');
        return;
      }
      if (e.target.closest('[data-month-next]')) {
        state.calendarAnchorDate = new Date(
          state.calendarAnchorDate.getFullYear(),
          state.calendarAnchorDate.getMonth() + 1,
          1,
        );
        actions.setView('calendar');
        return;
      }
      if (e.target.closest('[data-calendar-prev]')) {
        const step = ['week', 'load'].includes(state.calendarMode) ? 7 : 1;
        state.calendarAnchorDate = new Date(state.calendarAnchorDate);
        state.calendarAnchorDate.setDate(state.calendarAnchorDate.getDate() - step);
        actions.setView('calendar');
        return;
      }
      if (e.target.closest('[data-calendar-next]')) {
        const step = ['week', 'load'].includes(state.calendarMode) ? 7 : 1;
        state.calendarAnchorDate = new Date(state.calendarAnchorDate);
        state.calendarAnchorDate.setDate(state.calendarAnchorDate.getDate() + step);
        actions.setView('calendar');
        return;
      }
      const mode = e.target.closest('[data-calendar-mode]');
      if (mode) {
        actions.setCalendarMode(mode.dataset.calendarMode);
        actions.setView('calendar');
        return;
      }
      if (actions.handleCalendarLoadClick(e.target)) return;
      const personal = e.target.closest('[data-personal-event-id]');
      if (personal) {
        const found = state.personalEvents.find(
          (event) => event.id === personal.dataset.personalEventId,
        );
        if (found) return actions.openPersonalEventForm(found);
        return;
      }
      const appointment = e.target.closest('[data-appointment-id]');
      if (appointment) {
        const found = (
          state.lazyReads
            ? state.calendarRecords
            : state.data.flatMap((p) =>
                (p.appointments || []).map((a) => ({ ...a, patientId: p.id })),
              )
        ).find((a) => a.id === appointment.dataset.appointmentId);
        if (found) return actions.openAppointmentActions(found);
      }
      const slot = e.target.closest('[data-slot-date]');
      if (slot) return actions.openAppointmentForm(actions.calendarNewAppointment(slot, e));
      const nav = e.target.closest('[data-view]');
      if (nav) {
        actions.setView(nav.dataset.view);
        return;
      }
      const p = e.target.closest('[data-patient]');
      if (p) {
        state.selectedId = p.dataset.patient;
        state.activeTab = 'visits';
        actions.$('#search').value = '';
        actions.setView('card');
        return;
      }
      const tab = e.target.closest('[data-tab]');
      if (tab) {
        state.activeTab = tab.dataset.tab;
        actions.renderDetail();
        return;
      }
      if (e.target.closest('#more-visits')) return await actions.showMoreVisits();
      if (e.target.closest('#more-patient-appointments'))
        return await actions.showMorePatientAppointments();
      if (e.target.closest('#calendar-new'))
        return actions.openAppointmentForm(actions.calendarNewAppointment());
      if (e.target.closest('#add-patient')) return actions.openPatientForm();
      if (e.target.closest('#new-service')) return actions.openServiceForm();
      const editService = e.target.closest('[data-edit-service]');
      if (editService)
        return actions.openServiceForm(
          state.services.find((s) => s.id === editService.dataset.editService),
        );
      const deleteService = e.target.closest('[data-delete-service]');
      if (deleteService) {
        const service = state.services.find((s) => s.id === deleteService.dataset.deleteService);
        if (service && window.confirm(`Удалить услугу «${service.name}»?`)) {
          state.busy = true;
          state.services = state.services.filter((s) => s.id !== service.id);
          await actions.saveServices();
          actions.setView(state.currentView);
          actions.toast('Услуга удалена');
        }
        return;
      }
      if (e.target.closest('#new-visit') || e.target.closest('#empty-new'))
        return actions.openVisitForm();
      if (e.target.closest('#edit-patient') || e.target.closest('#edit-profile'))
        return actions.openPatientForm(actions.patient());
      const ev = e.target.closest('[data-edit-visit]');
      if (ev)
        return actions.openVisitForm(
          actions.patient().visits.find((v) => v.id === ev.dataset.editVisit),
        );
      const ph = e.target.closest('[data-photo]');
      if (ph) return actions.showPhoto(ph);
      if (e.target.closest('#back')) {
        state.selectedId = null;
        actions.renderList();
        actions.renderDetail();
      }
      if (e.target.closest('#close-editor') || e.target.closest('#cancel-editor'))
        await actions.requestEditorClose();
      if (e.target.closest('#close-photo')) actions.$('#photo-view').close();
      const rm = e.target.closest('[data-remove-photo]');
      if (rm) {
        const index = Number(rm.dataset.removePhoto);
        if (!state.editorMode?.appendOnly || index >= state.editorMode.savedPhotoCount) {
          state.uploadItems.splice(index, 1);
          actions.renderUploads();
        }
      }
    } catch (error) {
      if (logoutIntent && !logoutScopeMatches(logoutIntent)) return;
      actions.rollback();
      actions.toast(error.message);
    } finally {
      if (!logoutIntent || logoutScopeMatches(logoutIntent)) state.busy = false;
    }
  });
  actions.$('#search').addEventListener('input', actions.renderList);
  actions.$('#editor-form').addEventListener('submit', actions.submit);
  actions.$('#form-content').addEventListener('change', (e) => {
    if (e.target.id === 'photo-input') actions.processFiles(e.target.files);
    if (e.target.matches('[data-photo-caption], #photo-batch-caption'))
      actions.changePhotoCaption(e.target);
    if (e.target.id === 'appointment-patient') {
      document.querySelectorAll('.appointment-new-field').forEach((field) => {
        field.hidden = e.target.value !== '__new__';
      });
    }
  });
  actions.$('#client-filters').addEventListener('click', (e) => {
    const button = e.target.closest('[data-client-filter]');
    if (!button) return;
    state.clientFilter = button.dataset.clientFilter;
    actions.renderList();
  });
  document.querySelector('.name-sort').addEventListener('click', (e) => {
    const button = e.target.closest('[data-patient-sort]');
    if (!button) return;
    state.patientSort = button.dataset.patientSort;
    actions.renderList();
  });
  actions.bindEditorCloseEvents();
  actions.bindSettingsGuardEvents();
  actions.bindPhoneLandscapeEvents();
  state.mobileScreen?.addEventListener('change', (e) => {
    if (actions.preservePhoneCalendarOnResize()) return;
    if (state.calendarMode !== 'load') state.calendarMode = e.matches ? 'day' : 'week';
    if (state.currentView === 'calendar') actions.setView('calendar', { redraw: true });
  });
  window.addEventListener('pageshow', (e) => {
    if (e.persisted) {
      document.body.classList.add('app-loading');
      location.reload();
    }
  });
  window.addEventListener('storage', (e) => {
    if (e.key !== 'cartoteca-logout-v2') return;
    let marker;
    try {
      marker = JSON.parse(e.newValue);
    } catch {
      return;
    }
    if (
      !marker ||
      typeof marker.accountId !== 'string' ||
      !marker.accountId ||
      typeof marker.organizationId !== 'string' ||
      typeof marker.at !== 'number' ||
      !Number.isFinite(marker.at) ||
      marker.at <= 0 ||
      !logoutScopeMatches(marker)
    )
      return;
    actions.resetAssistant();
    location.replace('/');
  });
  window.addEventListener('beforeprint', () => {
    if (!actions.printablePatient()) actions.invalidatePrint();
  });
}

